def parse_git_status(
    status_text: str
) -> dict[str, list[str]]:
    res = {
        'staged': [],
        'unstaged': [],
        'untracked': []
    }
    for line in status_text.splitlines():
        if not line or len(line) < 4:
            continue
        code = line[:2]
        filename = line[3:].strip()
        if code == '??':
            res['untracked'].append(filename)
            continue
        if code[0] != ' ':
            res['staged'].append(filename)
        if code[1] in ('M', 'D'):
            res['unstaged'].append(filename)
    return res

