def parse_conflict_blocks(
    file_content: str
) -> list[dict[str, str]]:
    conflicts = []
    ours_lines = []
    theirs_lines = []
    state = 'NORMAL'
    for line in file_content.splitlines():
        if line.startswith('<<<<<<<'):
            state = 'OURS'
            ours_lines = []
            theirs_lines = []
        elif (
            line.startswith('=======')
            and state == 'OURS'
        ):
            state = 'THEIRS'
        elif (
            line.startswith('>>>>>>>')
            and state == 'THEIRS'
        ):
            th_txt = '\n'.join(theirs_lines)
            conflicts.append({
                'ours': '\n'.join(ours_lines),
                'theirs': th_txt
            })
            state = 'NORMAL'
        elif state == 'OURS':
            ours_lines.append(line)
        elif state == 'THEIRS':
            theirs_lines.append(line)
    return conflicts

