from unittest.mock import Mock

def fetch_with_retry(client, url: str, retries: int = 3) -> dict:
    for attempt in range(1, retries + 1):
        try:
            return client.get(url)
        except ConnectionError:
            if attempt == retries:
                raise
    return {}

client = Mock()
# Первые 2 вызова бросают исключение, 3-й возвращает успешный ответ
client.get.side_effect = [
    ConnectionError("Timeout 1"),
    ConnectionError("Timeout 2"),
    {"status": 200, "data": "ok"},
]

result = fetch_with_retry(client, "https://api.example.com/items")
assert result == {"status": 200, "data": "ok"}
assert client.get.call_count == 3
print("Успешно с попытки №", client.get.call_count)

