import re

VALID_TYPES = {'feat', 'fix', 'docs', 'style', 'refactor', 'test', 'chore'}

def validate_commit_message(msg: str) -> tuple[bool, str]:
    if not msg or not msg.strip():
        return (False, 'Пустое сообщение')
    header = msg.splitlines()[0].strip()
    if len(header) > 72:
        return (False, 'Превышен лимит 72 символа')
    if header.endswith('.'):
        return (False, 'Точка в конце заголовка запрещена')
    pattern = r'^([a-z]+)(?:\([a-z0-9_\-]+\))?:\s+(.+)$'
    match = re.match(pattern, header)
    if not match:
        return (False, 'Неверный формат Conventional Commits')
    ctype = match.group(1)
    if ctype not in VALID_TYPES:
        return (False, f'Недопустимый тип коммита: {ctype}')
    return (True, 'OK')

