def cherry_pick(parent_snapshot: dict[str, str], commit_snapshot: dict[str, str], target_snapshot: dict[str, str]) -> tuple[dict[str, str], list[str]]:
    result = dict(target_snapshot)
    conflicts = []

    all_keys = set(parent_snapshot.keys()).union(commit_snapshot.keys())
    delta = {}
    for k in all_keys:
        p_val = parent_snapshot.get(k)
        c_val = commit_snapshot.get(k)
        if p_val != c_val:
            delta[k] = (p_val, c_val)

    for path, (p_val, c_val) in delta.items():
        t_val = target_snapshot.get(path)
        if p_val is None:
            # Файл был добавлен коммитом
            if t_val is not None and t_val != c_val:
                conflicts.append(path)
            else:
                result[path] = c_val
        elif c_val is None:
            # Файл был удален коммитом
            if t_val != p_val:
                conflicts.append(path)
            else:
                result.pop(path, None)
        else:
            # Файл модифицирован
            if t_val != p_val:
                conflicts.append(path)
            else:
                result[path] = c_val

    conflicts.sort()
    return result, conflicts

