def advanced_cherry_pick(commit_meta: dict, target_snapshot: dict[str, str], allow_empty: bool = False, mainline: int | None = None) -> dict[str, str]:
    parents = commit_meta.get('parents', [])
    if len(parents) == 0:
        raise ValueError('Cannot cherry-pick root commit')
    if len(parents) > 1:
        if mainline is None:
            raise ValueError('Commit is a merge but no -m / mainline option was given')
        if not isinstance(mainline, int) or mainline < 1 or mainline > len(parents):
            raise ValueError('Commit has no parent mainline')
        base_parent = parents[mainline - 1]
    else:
        base_parent = parents[0]

    snapshot = commit_meta.get('snapshot', {})
    all_keys = set(base_parent.keys()).union(snapshot.keys())
    delta = {}
    for k in all_keys:
        p_v = base_parent.get(k)
        s_v = snapshot.get(k)
        if p_v != s_v:
            delta[k] = (p_v, s_v)

    if not delta:
        if not allow_empty:
            raise ValueError('Previous cherry-pick is empty')
        return dict(target_snapshot)

    result = dict(target_snapshot)
    conflicts = []
    for path, (p_v, s_v) in delta.items():
        t_v = target_snapshot.get(path)
        if p_v is None:
            if t_v is not None and t_v != s_v:
                conflicts.append(path)
            else:
                result[path] = s_v
        elif s_v is None:
            if t_v != p_v:
                conflicts.append(path)
            else:
                result.pop(path, None)
        else:
            if t_v != p_v:
                conflicts.append(path)
            else:
                result[path] = s_v

    if conflicts:
        conflicts.sort()
        raise RuntimeError(f'Cherry-pick conflict on: {conflicts}')

    return result

