def resolve_conflict_markers(content: str, strategy: str = 'ours', is_rebase: bool = False) -> str:
    if strategy not in ('ours', 'theirs', 'union'):
        raise ValueError(f'Unknown strategy: {strategy}')

    lines = content.splitlines()
    output = []
    state = 'NORMAL'
    ours_block = []
    theirs_block = []

    for line in lines:
        if line.startswith('<<<<<<<'):
            if state != 'NORMAL':
                raise ValueError('Malformed conflict markers')
            state = 'OURS'
            ours_block = []
            theirs_block = []
        elif line.startswith('======='):
            if state != 'OURS':
                raise ValueError('Malformed conflict markers')
            state = 'THEIRS'
        elif line.startswith('>>>>>>>'):
            if state != 'THEIRS':
                raise ValueError('Malformed conflict markers')
            state = 'NORMAL'
            side_ours = ours_block
            side_theirs = theirs_block
            if is_rebase:
                side_ours, side_theirs = side_theirs, side_ours

            if strategy == 'ours':
                output.extend(side_ours)
            elif strategy == 'theirs':
                output.extend(side_theirs)
            elif strategy == 'union':
                output.extend(side_ours)
                output.extend(side_theirs)
        else:
            if state == 'NORMAL':
                output.append(line)
            elif state == 'OURS':
                ours_block.append(line)
            elif state == 'THEIRS':
                theirs_block.append(line)

    if state != 'NORMAL':
        raise ValueError('Unterminated conflict marker')

    return '\n'.join(output)

