import difflib

def git_blame(commit_history: list[dict]) -> list[dict]:
    if not commit_history:
        return []

    # Состояние строк: list of (line_text, commit_id, author)
    current_annotated = []

    first = commit_history[0]
    first_lines = first['content'].splitlines()
    for line in first_lines:
        current_annotated.append((line, first['commit_id'], first['author']))

    for commit in commit_history[1:]:
        prev_lines = [item[0] for item in current_annotated]
        curr_lines = commit['content'].splitlines()
        matcher = difflib.SequenceMatcher(None, prev_lines, curr_lines)

        new_annotated = [None] * len(curr_lines)
        for tag, i1, i2, j1, j2 in matcher.get_opcodes():
            if tag == 'equal':
                for offset in range(i2 - i1):
                    new_annotated[j1 + offset] = current_annotated[i1 + offset]
            else:
                for j in range(j1, j2):
                    new_annotated[j] = (curr_lines[j], commit['commit_id'], commit['author'])
        current_annotated = new_annotated

    result = []
    for idx, item in enumerate(current_annotated, start=1):
        result.append({
            'line_num': idx,
            'content': item[0],
            'commit_id': item[1],
            'author': item[2]
        })
    return result

