        errors.append('tests directory must not be nested in src')

    # Packages under src must have __init__.py
    src_dirs = set()
    for p in file_paths:
        if p.startswith('src/'):
            parts = p.split('/')
            if len(parts) > 2 and p.endswith('.py'):
                dir_path = '/'.join(parts[:-1])
                src_dirs.add(dir_path)

    for d in src_dirs:
        init_path = f'{d}/__init__.py'
        if init_path not in file_paths:
            errors.append(f'Missing __init__.py in {d}')

