        color[u] = 'BLACK'

    for node in list(module_imports.keys()):
        if color[node] == 'WHITE':
            dfs(node, [node])

    errors.sort()
    cycles.sort()
    return {
        'is_valid': len(errors) == 0 and len(cycles) == 0,
        'errors': errors,
        'cycles': cycles
    }

