def validate_pr_merge_gate(pr_data: dict) -> dict:
    reasons = []
    author = pr_data.get('author', '')
    head_sha = pr_data.get('head_sha', '')
    min_approvals = pr_data.get('min_approvals', 1)

    # Последний отзыв от каждого ревьюера
    last_reviews = {}
    for rev in pr_data.get('reviews', []):
        reviewer = rev.get('reviewer')
        if reviewer == author:
            continue
        last_reviews[reviewer] = rev

    valid_approvals = []
    blockers = []
    for reviewer, rev in sorted(last_reviews.items()):
        state = rev.get('state')
        c_sha = rev.get('commit_sha')
        if state == 'CHANGES_REQUESTED' and c_sha == head_sha:
            blockers.append(reviewer)
        elif state == 'APPROVED' and c_sha == head_sha:
            valid_approvals.append(reviewer)

    if blockers:
        reasons.append(f'Changes requested by: {", ".join(blockers)}')

    if len(valid_approvals) < min_approvals:
        reasons.append(f'Insufficient approvals: got {len(valid_approvals)}, required {min_approvals}')

    # CI Checks
    required_checks = set(pr_data.get('required_ci_checks', []))
    completed_success = set()
    for check in pr_data.get('ci_checks', []):
        if check.get('status') == 'completed' and check.get('conclusion') == 'success':
            completed_success.add(check.get('name'))

    missing_ci = sorted(list(required_checks - completed_success))
    if missing_ci:
        reasons.append(f'Missing or failed required CI checks: {", ".join(missing_ci)}')

    reasons.sort()
    return {
        'can_merge': len(reasons) == 0,
        'reasons': reasons,
        'valid_approvals': sorted(valid_approvals)
    }

