class ContainerCowFS:
    def __init__(self, base_layers: list[dict[str, str]]):
        # Deepcopy or shallow copy of layers to preserve immutability
        self.base_layers = [dict(layer) for layer in base_layers]
        self.upper = {}

    def _norm(self, path: str) -> str:
        return path.replace('\\', '/').strip('/')

    def _wh_path(self, path: str) -> str:
        norm = self._norm(path)
        parts = norm.split('/')
        dirname = '/'.join(parts[:-1])
        filename = f".wh.{parts[-1]}"
        return f"{dirname}/{filename}" if dirname else filename

    def _get_base_content(self, norm_path: str) -> str | None:
        curr = None
        for layer in self.base_layers:
            for p, c in layer.items():
                p_norm = self._norm(p)
                parts = p_norm.split('/')
                fname = parts[-1]
                dname = '/'.join(parts[:-1])
                if fname.startswith('.wh.'):
                    target = f"{dname}/{fname[4:]}" if dname else fname[4:]
                    if target == norm_path:
                        curr = None
                elif p_norm == norm_path:
                    curr = c
        return curr

    def read(self, path: str) -> str | None:
        norm = self._norm(path)
        wh = self._wh_path(norm)
        if wh in self.upper:
            return None
        if norm in self.upper:
            return self.upper[norm]
        return self._get_base_content(norm)

    def write(self, path: str, content: str) -> None:
        norm = self._norm(path)
        wh = self._wh_path(norm)
        self.upper.pop(wh, None)
        self.upper[norm] = content

    def delete(self, path: str) -> bool:
        norm = self._norm(path)
        curr = self.read(norm)
        if curr is None:
            return False

        base_val = self._get_base_content(norm)
        self.upper.pop(norm, None)
        if base_val is not None:
            wh = self._wh_path(norm)
            self.upper[wh] = ''
        return True

    def get_diff(self) -> dict:
        added = []
        modified = []
        deleted = []

        for p, c in self.upper.items():
            parts = p.split('/')
            fname = parts[-1]
            dname = '/'.join(parts[:-1])
            if fname.startswith('.wh.'):
                orig_name = fname[4:]
                orig_path = f"{dname}/{orig_name}" if dname else orig_name
                deleted.append(orig_path)
            else:
                base_val = self._get_base_content(p)
                if base_val is None:
                    added.append(p)
                else:
                    if base_val != c:
                        modified.append(p)

        return {
            'added': sorted(added),
            'modified': sorted(modified),
            'deleted': sorted(deleted)
        }

