def schedule_compose_startup(services: dict[str, dict]) -> list[list[str]]:
    if not services:
        return []

    all_service_names = set(services.keys())
    deps_map = {}

    for s_name, conf in services.items():
        dep_entry = conf.get('depends_on', [])
        if isinstance(dep_entry, dict):
            direct_deps = set(dep_entry.keys())
        elif isinstance(dep_entry, list):
            direct_deps = set(dep_entry)
        else:
            direct_deps = set()

        for d in direct_deps:
            if d not in all_service_names:
                raise ValueError(f"Unknown service dependency: {d}")
        deps_map[s_name] = set(direct_deps)

    waves = []
    resolved = set()
    remaining = set(all_service_names)

    while remaining:
        current_wave = []
        for s in sorted(remaining):
            if deps_map[s].issubset(resolved):
                current_wave.append(s)

        if not current_wave:
            raise ValueError("Circular dependency detected")

        waves.append(current_wave)
        for s in current_wave:
            resolved.add(s)
            remaining.remove(s)

    return waves

