def interpolate_compose_env(template: str, env_vars: dict[str, str]) -> str:
    import re

    # Replace $$ with a unique placeholder
    PLACEHOLDER = '__DOUBLE_DOLLAR_ESCAPED__'
    t = template.replace('$$', PLACEHOLDER)

    pattern = re.compile(r'\$(?:\{([a-zA-Z_][a-zA-Z0-9_]*)(?::?-|:?\?)(.*?)\}|([a-zA-Z_][a-zA-Z0-9_]*|\{[a-zA-Z_][a-zA-Z0-9_]*\}))')

    # Full pattern matching:
    # 1. ${VAR:-default} or ${VAR-default}
    # 2. ${VAR:?err} or ${VAR?err}
    # 3. ${VAR}
    # 4. $VAR
    full_pattern = re.compile(r'\$(\{([a-zA-Z_][a-zA-Z0-9_]*)(:[?-]|[?-])([^}]*)\}|\{([a-zA-Z_][a-zA-Z0-9_]*)\}|([a-zA-Z_][a-zA-Z0-9_]*))')

    def replacer(match):
        # group 2: var name with modifier
        # group 3: modifier (':-', '-', ':?', '?')
        # group 4: arg (default or error message)
        # group 5: simple braced var
        # group 6: simple bare var
        if match.group(2) is not None:
            var = match.group(2)
            op = match.group(3)
            val = match.group(4)
            is_set = var in env_vars
            raw_val = env_vars.get(var, '')
            is_empty = (not raw_val)

            if op == ':-':
                return val if (not is_set or is_empty) else raw_val
            elif op == '-':
                return val if not is_set else raw_val
            elif op == ':?':
                if not is_set or is_empty:
                    raise ValueError(val or f"Variable {var} is missing or empty")
                return raw_val
            elif op == '?':
                if not is_set:
                    raise ValueError(val or f"Variable {var} is missing")
                return raw_val
        elif match.group(5) is not None:
            var = match.group(5)
            return env_vars.get(var, '')
        elif match.group(6) is not None:
            var = match.group(6)
            return env_vars.get(var, '')
        return match.group(0)

    result = full_pattern.sub(replacer, t)
    return result.replace(PLACEHOLDER, '$')

