def parse_docker_run_args(args: list[str]) -> dict:
    import re

    def parse_memory(val: str) -> int:
        val = val.strip().lower()
        units = {'b': 1, 'k': 1024, 'm': 1024**2, 'g': 1024**3}
        unit = 'b'
        num_str = val
        if val and val[-1] in units:
            unit = val[-1]
            num_str = val[:-1]
        try:
            num = float(num_str)
            if num <= 0:
                raise ValueError()
            return int(num * units[unit])
        except Exception:
            raise ValueError(f"Invalid memory value: {val}")

    def parse_port(spec: str) -> dict:
        spec = spec.strip()
        protocol = 'tcp'
        if '/' in spec:
            spec, protocol = spec.rsplit('/', 1)
            protocol = protocol.lower()
            if protocol not in ('tcp', 'udp'):
                raise ValueError("Invalid protocol")

        parts = spec.split(':')
        host_ip = '0.0.0.0'
        host_port = None

        if len(parts) == 1:
            c_port = int(parts[0])
        elif len(parts) == 2:
            host_port = int(parts[0])
            c_port = int(parts[1])
        elif len(parts) == 3:
            host_ip = parts[0] or '0.0.0.0'
            host_port = int(parts[1])
            c_port = int(parts[2])
        else:
            raise ValueError("Invalid port spec")

        for p in (host_port, c_port):
            if p is not None and not (1 <= p <= 65535):
                raise ValueError(f"Port {p} out of range 1..65535")

        return {
            'host_ip': host_ip,
            'host_port': host_port,
            'container_port': c_port,
            'protocol': protocol
