            c_port = int(parts[1])
        elif len(parts) == 3:
            host_ip = parts[0] or '0.0.0.0'
            host_port = int(parts[1])
            c_port = int(parts[2])
        else:
            raise ValueError("Invalid port spec")

        for p in (host_port, c_port):
            if p is not None and not (1 <= p <= 65535):
                raise ValueError(f"Port {p} out of range 1..65535")

