def simulate_cgroups_runtime(processes: list[dict], memory_limit_mb: int, cpu_quota_us: int, cpu_period_us: int = 100000) -> dict:
    if not processes:
        return {'throttled_ms': 0.0, 'killed_pids': [], 'final_rss_mb': 0, 'container_panicked': False}

    # 1. CPU throttling
    max_cpu_ms = (cpu_quota_us / 1000.0)
    total_cpu_demanded = sum(p['cpu_demanded_ms'] for p in processes)
    throttled_ms = max(0.0, float(total_cpu_demanded - max_cpu_ms))

    # 2. Memory & OOM Killer
    alive = list(processes)
    total_rss = sum(p['rss_mb'] for p in alive)
    killed_pids = []

    if total_rss > memory_limit_mb:
        # Loop killing candidates
        while total_rss > memory_limit_mb:
            candidates = [p for p in alive if p.get('oom_score_adj', 0) != -1000]
            if not candidates:
                # All remaining are unkillable
                break

            def calc_score(p):
                score = (p['rss_mb'] / memory_limit_mb) * 1000.0 + p.get('oom_score_adj', 0)
                return (score, p['rss_mb'], -p['pid'])

            victim = max(candidates, key=calc_score)
            alive.remove(victim)
            killed_pids.append(victim['pid'])
            total_rss -= victim['rss_mb']

    container_panicked = (total_rss > memory_limit_mb)

    return {
        'throttled_ms': round(throttled_ms, 2),
        'killed_pids': killed_pids,
        'final_rss_mb': total_rss,
        'container_panicked': container_panicked
    }

