def analyze_build_context(file_tree: dict[str, int], dockerignore_rules: list[str], top_k: int = 3) -> dict:
    import fnmatch

    total_files = len(file_tree)
    total_bytes = sum(file_tree.values())

    cleaned_rules = []
    for r in dockerignore_rules:
        r_str = r.strip()
        if not r_str or r_str.startswith('#'):
            continue
        cleaned_rules.append(r_str)

    def is_ignored(path: str) -> bool:
        norm_path = path.replace('\\', '/').strip('/')
        ignored = False

        for rule in cleaned_rules:
            is_negation = rule.startswith('!')
            pat = rule[1:] if is_negation else rule
            pat = pat.replace('\\', '/').strip()

            matched = False
            # Directory match
            if pat.endswith('/'):
                dir_pat = pat.rstrip('/')
                if norm_path.startswith(dir_pat + '/') or norm_path == dir_pat:
                    matched = True
            else:
                # Direct match or any component match
                if fnmatch.fnmatch(norm_path, pat) or fnmatch.fnmatch(norm_path, f"*/{pat}"):
                    matched = True
                elif norm_path.startswith(pat + '/'):
                    matched = True
                else:
                    # Match filename
                    fname = norm_path.split('/')[-1]
                    if fnmatch.fnmatch(fname, pat):
                        matched = True

            if matched:
                ignored = not is_negation

        return ignored

    included = []
    for p, sz in file_tree.items():
        if not is_ignored(p):
            included.append((p.replace('\\', '/').strip('/'), sz))

    included.sort(key=lambda x: x[0])
    inc_paths = [x[0] for x in included]
    inc_bytes = sum(x[1] for x in included)

    # Top heavy
    top_heavy = sorted(included, key=lambda x: (-x[1], x[0]))[:top_k]
    top_heavy_list = [{'path': p, 'size': sz} for p, sz in top_heavy]

    return {
        'total_files_count': total_files,
        'total_initial_bytes': total_bytes,
        'included_files': inc_paths,
        'included_bytes': inc_bytes,
        'bytes_saved': total_bytes - inc_bytes,
        'top_heavy_files': top_heavy_list
    }

