def analyze_multistage_dag(stages: list[dict], target_stage: str | None = None) -> dict:
    if not stages:
        return {'executed_stages': [], 'pruned_stages': [], 'final_image_size_mb': 0}

    # Map name and string index to stage dict and index
    name_to_idx = {}
    for s in stages:
        idx = s['index']
        name_to_idx[str(idx)] = idx
        if s.get('name'):
            name_to_idx[s['name']] = idx

    # Determine target index
    if target_stage is None:
        target_idx = stages[-1]['index']
    else:
        if str(target_stage) in name_to_idx:
            target_idx = name_to_idx[str(target_stage)]
        else:
            raise ValueError(f"Target stage '{target_stage}' not found")

    # Build adjacency list: dependencies of stage
    # stage -> list of stages it depends on
    stage_deps = {s['index']: set() for s in stages}
    base_chain = {s['index']: None for s in stages}

    for s in stages:
        idx = s['index']
        # 1. Base image
        base_img = s.get('base_image')
        if base_img and base_img in name_to_idx:
            parent_idx = name_to_idx[base_img]
            stage_deps[idx].add(parent_idx)
            base_chain[idx] = parent_idx

        # 2. copy_from
        for cf in s.get('copy_from', []):
            if str(cf) in name_to_idx:
                dep_idx = name_to_idx[str(cf)]
                stage_deps[idx].add(dep_idx)

    # Reachability from target_idx using reverse traversal
    needed = set()
    stack = [target_idx]
    while stack:
        curr = stack.pop()
        if curr not in needed:
            needed.add(curr)
            for parent in stage_deps.get(curr, []):
                if parent not in needed:
                    stack.append(parent)

    # Pruned stages
    all_indices = [s['index'] for s in stages]
    pruned = sorted([i for i in all_indices if i not in needed])

    # Topo sort of needed
    executed = []
    in_degree = {i: len(stage_deps[i].intersection(needed)) for i in needed}
    queue = sorted([i for i in needed if in_degree[i] == 0])

    while queue:
        curr = queue.pop(0)
        executed.append(curr)
        for child in needed:
            if curr in stage_deps[child]:
                in_degree[child] -= 1
                if in_degree[child] == 0:
                    queue.append(child)
        queue.sort()

    # Calculate final image size: follow base_chain of target_idx
    size_mb = 0
    curr_base = target_idx
    idx_map = {s['index']: s for s in stages}
    while curr_base is not None:
        size_mb += idx_map[curr_base].get('size_mb', 0)
        curr_base = base_chain.get(curr_base)

    return {
        'executed_stages': executed,
        'pruned_stages': pruned,
        'final_image_size_mb': size_mb
    }

