def validate_multistage_dockerfile(dockerfile_text: str) -> list[str]:
    import re

    lines = dockerfile_text.splitlines()
    errors = []

    declared_stages_names = set()
    current_stage_idx = -1
    stage_found = False

    from_pattern = re.compile(r'^\s*FROM\s+(\S+)(?:\s+[aA][sS]\s+(\S+))?', re.IGNORECASE)
    copy_from_pattern = re.compile(r'--from=(\S+)', re.IGNORECASE)

    for line in lines:
        line_clean = line.strip()
        if not line_clean or line_clean.startswith('#'):
            continue

        from_match = from_pattern.match(line_clean)
        if from_match:
            stage_found = True
            current_stage_idx += 1
            base_img = from_match.group(1)
            stage_name = from_match.group(2)

            if stage_name:
                stage_name_lower = stage_name.lower()
                if stage_name_lower in declared_stages_names:
                    errors.append(f"DUPLICATE_STAGE_NAME: {stage_name}")
                declared_stages_names.add(stage_name_lower)

            if stage_name and base_img.lower() == stage_name.lower():
                errors.append("CIRCULAR_STAGE_DEPENDENCY")
            continue

        # Check COPY --from
        if line_clean.upper().startswith('COPY'):
            copy_match = copy_from_pattern.search(line_clean)
            if copy_match:
                ref = copy_match.group(1).strip()
                if ref.isdigit():
                    idx_val = int(ref)
                    if idx_val >= current_stage_idx or idx_val < 0:
                        errors.append(f"INVALID_STAGE_INDEX: {ref}")
                else:
                    if ref.lower() not in declared_stages_names:
                        errors.append(f"UNKNOWN_STAGE_REF: {ref}")

    if not stage_found:
        errors.append('NO_STAGES_DEFINED')

    return errors

