    matching_ips = set()
    for net_name in source_networks:
        net_data = network_topology[net_name]
        containers = net_data.get('containers', {})
        for c_name, c_data in containers.items():
            aliases = c_data.get('aliases', [])
            if c_name == query_name or query_name in aliases:
                matching_ips.add(c_data['ip'])

    return sorted(list(matching_ips))

