import ipaddress

class DockerIpamAllocator:
    def __init__(self, parent_pool_cidr: str):
        self.parent_net = ipaddress.ip_network(parent_pool_cidr, strict=True)
        self.allocated = []

    def is_overlapping(self, cidr: str) -> bool:
        target = ipaddress.ip_network(cidr, strict=False)
        return any(target.overlaps(net) for net in self.allocated)

    def allocate_subnet(self, prefix_len: int) -> dict:
        if prefix_len < self.parent_net.prefixlen:
            raise ValueError(f"Requested prefix /{prefix_len} cannot fit in parent /{self.parent_net.prefixlen}")

        for candidate in self.parent_net.subnets(new_prefix=prefix_len):
            if not any(candidate.overlaps(active) for active in self.allocated):
                self.allocated.append(candidate)
                self.allocated.sort(key=lambda n: n.network_address)

                if candidate.num_addresses <= 2:
                    usable = 0
                    gw = str(candidate.network_address)
                else:
                    usable = candidate.num_addresses - 2
                    gw = str(candidate.network_address + 1)

                return {
                    'subnet': str(candidate),
                    'gateway': gw,
                    'broadcast': str(candidate.broadcast_address),
                    'usable_hosts_count': usable
                }

        raise ValueError("Pool exhausted")

    def release_subnet(self, subnet_cidr: str) -> bool:
        target = ipaddress.ip_network(subnet_cidr, strict=False)
        for i, net in enumerate(self.allocated):
            if net == target:
                self.allocated.pop(i)
                return True
        return False

