def simulate_rolling_update(replicas: int, max_surge: int | str, max_unavailable: int | str, steps_limit: int = 20) -> list[dict]:
    import math

    if replicas == 0:
        return [{'old': 0, 'new': 0}]

    def parse_param(val, is_surge: bool) -> int:
        if isinstance(val, str) and val.endswith('%'):
            pct = float(val[:-1])
            raw = (replicas * pct) / 100.0
            return math.ceil(raw) if is_surge else math.floor(raw)
        return int(val)

    surge_val = parse_param(max_surge, True)
    unavail_val = parse_param(max_unavailable, False)

    if surge_val == 0 and unavail_val == 0:
        raise ValueError("Deadlock: both surge and unavailable are 0")

    max_allowed = replicas + surge_val
    min_available = max(0, replicas - unavail_val)

    old_pods = replicas
    new_pods = 0

    history = [{'old': old_pods, 'new': new_pods}]
    step = 0

    while (old_pods > 0 or new_pods < replicas) and step < steps_limit:
        step += 1
        changed = False

        # Phase A: scale up new pods
        can_add = min(max_allowed - (old_pods + new_pods), replicas - new_pods)
        if can_add > 0:
            new_pods += can_add
            changed = True
            history.append({'old': old_pods, 'new': new_pods})

        # Phase B: terminate old pods
        can_remove = (old_pods + new_pods) - min_available
        if can_remove > 0 and old_pods > 0:
            to_remove = min(old_pods, can_remove)
            if new_pods < replicas:
                to_remove = min(to_remove, (old_pods + new_pods) - replicas)
            if to_remove > 0:
                old_pods -= to_remove
                changed = True
                history.append({'old': old_pods, 'new': new_pods})

        if not changed:
            # Force advance
            if old_pods > 0 and (old_pods + new_pods - 1 >= min_available):
                old_pods -= 1
                history.append({'old': old_pods, 'new': new_pods})
            elif new_pods < replicas:
                new_pods += 1
                history.append({'old': old_pods, 'new': new_pods})
            else:
                break

    if history[-1] != {'old': 0, 'new': replicas}:
        history.append({'old': 0, 'new': replicas})

    return history

