def sync_service_endpoints(service: dict, pods: list[dict]) -> dict:
    svc_name = service.get('metadata', {}).get('name', '')
    selector = service.get('spec', {}).get('selector', {})

    if not selector:
        return {'service_name': svc_name, 'ready_endpoints': [], 'not_ready_endpoints': []}

    ready = []
    not_ready = []

    for pod in pods:
        labels = pod.get('metadata', {}).get('labels', {})
        if any(labels.get(k) != v for k, v in selector.items()):
            continue

        status = pod.get('status', {})
        if status.get('phase') != 'Running':
            continue
        ip = status.get('pod_ip')
        if not ip:
            continue

        p_name = pod.get('metadata', {}).get('name', '')
        n_name = pod.get('spec', {}).get('node_name', '')
        ep = {'ip': ip, 'pod_name': p_name, 'node_name': n_name}

        is_terminating = bool(pod.get('metadata', {}).get('deletion_timestamp'))
        conditions = status.get('conditions', [])
        is_ready = any(c.get('type') == 'Ready' and c.get('status') == 'True' for c in conditions)

        if is_ready and not is_terminating:
            ready.append(ep)
        else:
            not_ready.append(ep)

    ready.sort(key=lambda x: x['ip'])
    not_ready.sort(key=lambda x: x['ip'])

    return {
        'service_name': svc_name,
        'ready_endpoints': ready,
        'not_ready_endpoints': not_ready
    }

